import zipfile, re, base64

config_str = """"""

raw_bytes = base64.b64decode(config_str.strip())
print(f"Decoded length: {len(raw_bytes)}")

# Let's search in yacine.apk for decryption keys or methods
apk_path = r'10_SCRATCH_AND_TOOLS\yacine.apk'
with zipfile.ZipFile(apk_path, 'r') as z:
    for dex_name in ['classes.dex', 'classes2.dex']:
        dex = z.read(dex_name)
        # Find references to "config"
        for match in re.finditer(rb'config', dex):
            pos = match.start()
            # print surrounding
            snippet = dex[max(0, pos-40):min(len(dex), pos+40)]
            if b'prefs' in snippet.lower() or b'shared' in snippet.lower() or b'app' in snippet.lower():
                print(f"Found near prefs in {dex_name}: {snippet}")
